    checks = {check['id']: check for check in body['checks']}
    assert checks['discovery-facts-present']['status'] == 'pass'
    assert checks['discovery-facts-complete']['status'] == 'pass'
    assert checks['promotion-disabled']['status'] == 'blocked'


