def test_job_submit_persists_status_logs_and_history(client, auth_headers, monkeypatch):
    """Submit-only jobs are executed by the background worker and persisted."""
    import subprocess
    import time

    class FakeProc:
        returncode = 0
        stdout = iter(['Connecting to Prism Central\n', 'ok\n'])
        stderr = iter([])
        def wait(self): pass
        def kill(self): pass
        def poll(self): return 0

    monkeypatch.setattr(subprocess, 'Popen', lambda *a, **kw: FakeProc())

    resp = client.post('/api/jobs',
                       json={'script': 'AddAdServerPe', 'configFile': 'test.yml'},
                       headers=auth_headers)
    assert resp.status_code == 202
    job_id = resp.get_json()['id']

    job = None
    for _ in range(30):
        job = client.get(f'/api/jobs/{job_id}', headers=auth_headers).get_json()
        if job['status'] == 'success':
            break
        time.sleep(0.05)

    assert job['status'] == 'success'
    assert job['progress']['phase'] == 'Completed'
    assert job['progress']['percent'] == 100
    assert job['progress']['estimated'] is True
    assert any(event['type'] == 'stdout' and event['data'] == 'ok' for event in job['logs'])

    jobs = client.get('/api/jobs', headers=auth_headers).get_json()
    assert jobs[0]['id'] == job_id

    history = client.get('/api/executions', headers=auth_headers).get_json()
    assert history[0]['id'] == job_id
    assert history[0]['status'] == 'success'


def test_standalone_fca_success_job_is_labelled_as_handoff(client, auth_headers, monkeypatch):
    """Accepted standalone FCA jobs should not read like completed cluster deployments."""
    import time
    import server

    client.post('/api/settings',
                json={'approvalRequiredWorkflows': []},
                headers=auth_headers)

    monkeypatch.setattr(server, '_execute_standalone_fca_lifecycle', lambda workflow, config: (
        True,
        ['FCA submit accepted: HTTP 201', 'FCA status still RUNNING after 30 polls (60 seconds); treating accepted Lifecycle submission as successful handoff.'],
        {'fcaStatusPollingExpired': True},
    ))

    yaml_body = (
        'ztf_orchestrator:\n'
        '  foundation_central_target: standalone_fca\n'
        'fca_api_version: v4.2.a2\n'
        'fca_ip: 192.0.2.122\n'
        'fca_credential: foundation_central\n'
    )
    workflows = {
        'cluster-create-standalone-fca': 'create_fca_cluster.yml',
        'imaging-only-standalone-fca': 'imaging_only_fca.yml',
        'imaging-standalone-fca': 'pod-deploy-fca.yml',
        'site-deploy-standalone-fca': 'sites-deploy-fca.yml',
    }
    for workflow, config_file in workflows.items():
        resp = client.post('/api/jobs',
                           json={'workflow': workflow,
                                 'configContent': yaml_body,
                                 'configFile': config_file,
                                 'destructiveConfirmation': f'RUN STANDALONE-FCA {workflow}'},
                           headers=auth_headers)
        assert resp.status_code == 202
        job_id = resp.get_json()['id']

        job = None
        for _ in range(30):
            job = client.get(f'/api/jobs/{job_id}', headers=auth_headers).get_json()
            if job['status'] == 'success':
                break
            time.sleep(0.05)

        assert job['status'] == 'success'
        assert job['progress']['phase'] == 'FCA handoff accepted'
        assert 'Monitor Foundation Central' in job['progress']['detail']


