def test_audit_log_passes_filters_to_storage(client, auth_headers, monkeypatch):
    """Audit log endpoint forwards operator-facing filters to storage."""
    import server

    captured = {}

    class AuditStorage:
        def read_audit_events(
            self,
            limit=200,
            level='',
            user='',
            action='',
            include_http=True,
            include_routine=True,
        ):
            captured.update({
                'limit': limit,
                'level': level,
                'user': user,
                'action': action,
                'include_http': include_http,
                'include_routine': include_routine,
            })
            return [{'msg': 'login_success', 'event': 'auth'}]

    monkeypatch.setattr(server, '_storage', AuditStorage())
    resp = client.get(
        '/api/audit-log?level=info&user=admin&action=login&include_http=false&include_routine=false&limit=25',
        headers=auth_headers,
    )

    assert resp.status_code == 200
    assert resp.get_json() == [{'msg': 'login_success', 'event': 'auth'}]
    assert captured == {
        'limit': 25,
        'level': 'INFO',
        'user': 'admin',
        'action': 'login',
        'include_http': False,
        'include_routine': False,
    }


